(()=>{const art={"routes":"data:image/png;base64,","visa":"data:image/png;base64,","stay":"data:image/png;base64,","day":"data:image/png;base64,"};const target=()=>document.querySelector('.stage-character');function sync(){const el=target(),active=document.querySelector('.screen.active');if(!el)return;const id=active?.id||'routes';if(art[id]){el.style.backgroundImage='url("'+art[id]+'")';el.dataset.pose=id;el.classList.add('is-visible')}}function start(){sync();document.addEventListener('click',()=>{setTimeout(sync,40);setTimeout(sync,180)});const root=document.querySelector('.planner')||document.body;new MutationObserver(sync).observe(root,{subtree:true,attributes:true,attributeFilter:['class']})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start):start()})();